import WidgetKit
import SwiftUI
import ImageIO

@main
struct DashboardBundle: WidgetBundle {
  var body: some Widget { SalesWidget() }   // the extension's own entry point, not the app's
}

enum SharedStore {
  static let groupID = "group.com.example.dashboard"

  static var container: URL {
    FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: groupID)!
  }

  // Decoded at display size — a full-size decode is what jetsams a 30 MB process.
  static func thumbnail(named name: String, maxPixel: CGFloat) -> CGImage? {
    let url = container.appending(path: name)
    let options: [CFString: Any] = [
      kCGImageSourceCreateThumbnailFromImageAlways: true,
      kCGImageSourceThumbnailMaxPixelSize: maxPixel,
      kCGImageSourceShouldCacheImmediately: true
    ]
    guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return nil }
    return CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary)
  }
}

