struct SalesEntry: TimelineEntry {
  let date: Date
  let total: Decimal
  let store: StoreEntity
}

struct SalesProvider: AppIntentTimelineProvider {
  // Synchronous and instant: the redacted skeleton behind the real view.
  func placeholder(in context: Context) -> SalesEntry {
    SalesEntry(date: .now, total: 1234, store: .sample)
  }

  // The gallery, the first appearance, transient system UI.
  func snapshot(for configuration: SelectStoreIntent,
                in context: Context) async -> SalesEntry {
    if context.isPreview {
      return SalesEntry(date: .now, total: 1234, store: .sample)   // no I/O, no network
    }
    return await SalesStore.cachedEntry(for: configuration.store)
        ?? placeholder(in: context)
  }

  // The only callback allowed to be slow — and only by a few seconds.
  func timeline(for configuration: SelectStoreIntent,
                in context: Context) async -> Timeline<SalesEntry> {
    let hours = await SalesStore.hourlyTotals(for: configuration.store)
    let entries = hours.map {
      SalesEntry(date: $0.hour, total: $0.amount, store: configuration.store)
    }
    return Timeline(entries: entries, policy: .atEnd)
  }
}

// WRONG: the gallery waits on the network and then draws whatever came back —
// which, in a freshly installed extension, is the signed-out view.
// func snapshot(for c: SelectStoreIntent, in ctx: Context) async -> SalesEntry {
//   await SalesAPI.today()
// }

func timeline(for configuration: SalesIntent,
              in context: Context) async -> Timeline<SalesEntry> {
  let hours = await SalesStore.forecast(for: configuration.store)
  let entries = hours.map { SalesEntry(date: $0.start, total: $0.total) }

  // WRONG: one entry dated now with .atEnd asks for a reload immediately, forever.
  // return Timeline(entries: [SalesEntry(date: .now, total: today)], policy: .atEnd)

  // Ask again only when the number can actually differ.
  return Timeline(entries: entries, policy: .after(SalesStore.nextOpeningBell))
}

// In the app, right after a write the widget must reflect:
func didRecordSale() throws {
  try store.save()
  WidgetCenter.shared.reloadTimelines(ofKind: "SalesWidget")
}

// Reload only the kinds the user actually placed.
func reloadPlacedWidgets() async {
  let placed = (try? await WidgetCenter.shared.currentConfigurations()) ?? []
  for widget in Set(placed.map(\.kind)) {
    WidgetCenter.shared.reloadTimelines(ofKind: widget)
  }
}

// None of that runs while the app is dead — a silent push wakes it first.
func application(_ app: UIApplication,
                 didReceiveRemoteNotification info: [AnyHashable: Any]) async
                 -> UIBackgroundFetchResult {
  await SalesStore.sync()
  WidgetCenter.shared.reloadTimelines(ofKind: "SalesWidget")
  return .newData
}

struct ShiftEntry: TimelineEntry {
  let date: Date
  let shift: Shift
  var relevance: TimelineEntryRelevance?
}

// Budget-friendly: one reload produces entries for the whole day.
func timeline(for configuration: ShiftIntent,
              in context: Context) async -> Timeline<ShiftEntry> {
  let shifts = await Roster.shifts(on: .now)

  let entries = shifts.map { shift in
    ShiftEntry(date: shift.start,
               shift: shift,
               // Relevance lets a Smart Stack surface the widget when it matters,
               // instead of you refreshing more often to be noticed.
               relevance: TimelineEntryRelevance(score: shift.isNext ? 100 : 10))
  }

  // Nothing can change until tomorrow's roster is published: don't ask before then.
  return Timeline(entries: entries, policy: .after(Roster.nextPublication))
}

// WRONG shape: a one-minute poll trying to out-run the budget.
// The first hour works, the rest of the day is silence.
// return Timeline(entries: [ShiftEntry(date: .now, shift: current, relevance: nil)],
//                 policy: .after(.now.addingTimeInterval(60)))

// The escape hatch for unpredictable changes — a silent push, not a shorter interval.
func handleRosterPush() async {
  await Roster.sync()
  WidgetCenter.shared.reloadTimelines(ofKind: "ShiftWidget")
}

import AppIntents
import WidgetKit

struct ProjectEntity: AppEntity {
  let id: String
  let name: String

  static let typeDisplayRepresentation: TypeDisplayRepresentation = "Project"
  var displayRepresentation: DisplayRepresentation { DisplayRepresentation(title: "\(name)") }
  static let defaultQuery = ProjectQuery()
}

struct ProjectQuery: EntityQuery {
  // Resolves a pick made months ago — it must survive a deleted project.
  func entities(for identifiers: [String]) async throws -> [ProjectEntity] {
    SharedCache.projects().filter { identifiers.contains($0.id) }
  }

  // The picker's list. Runs in the widget extension, so read the App Group cache:
  // a cold API call here is a configuration sheet that spins.
  func suggestedEntities() async throws -> [ProjectEntity] {
    SharedCache.projects()
  }
}

struct SelectProjectIntent: WidgetConfigurationIntent {
  static let title: LocalizedStringResource = "Select Project"

  @Parameter(title: "Project") var project: ProjectEntity?
}

struct ProjectWidget: Widget {
  var body: some WidgetConfiguration {
    AppIntentConfiguration(kind: "ProjectWidget",
                           intent: SelectProjectIntent.self,
                           provider: ProjectProvider()) { entry in
      ProjectView(entry: entry)
    }
    .supportedFamilies([.systemSmall, .systemMedium])
  }
}

