import AppIntents
import WidgetKit
import SwiftUI

struct CompleteTaskIntent: AppIntent {
  static let title: LocalizedStringResource = "Complete task"

  @Parameter(title: "Task") var taskID: String

  init() {}
  init(taskID: String) { self.taskID = taskID }

  func perform() async throws -> some IntentResult {
    // Runs in the background, outside the render pass, with a few seconds and no UI.
    // Write it where the widget can read it back.
    SharedTasks.markDone(taskID)
    return .result()
  }
}

struct TodoRow: View {
  let item: TodoItem

  var body: some View {
    HStack {
      Button(intent: CompleteTaskIntent(taskID: item.id)) {
        Image(systemName: item.isDone ? "checkmark.circle.fill" : "circle")
      }
      .buttonStyle(.plain)

      Text(item.title)
        .strikethrough(item.isDone)
        .invalidatableContent()   // drawn "pending" the instant the intent starts

      // WRONG: a widget ignores gestures entirely, so this tap just opens the app.
      // Image(systemName: "circle").onTapGesture { complete(item) }
    }
  }
}

struct OrdersWidgetView: View {
  let entry: OrdersEntry
  @Environment(\.widgetFamily) private var family

  var body: some View {
    VStack(alignment: .leading) {
      ForEach(entry.orders) { order in
        if family == .systemMedium || family == .systemLarge {
          Link(destination: URL(string: "brewlog://order/\(order.id)")!) {
            OrderRow(order: order)      // per-row destination
          }
        } else {
          OrderRow(order: order)        // small and accessory: Link would be ignored
        }
      }
    }
    // Exactly one, at the root: the fallback for taps that hit no Link, and the
    // only link a small or Lock Screen widget has at all.
    .widgetURL(URL(string: "brewlog://orders")!)
  }
}

// In the app — usually a cold launch, so the URL has to carry everything.
@main
struct BrewlogApp: App {
  @State private var route = Route.orders

  var body: some Scene {
    WindowGroup {
      RootView(route: $route)
        .onOpenURL { url in
          guard url.scheme == "brewlog" else { return }
          route = url.host() == "order"
            ? .order(id: url.lastPathComponent)   // a stable id, never an index
            : .orders
        }
    }
  }
}

import ActivityKit

struct DeliveryAttributes: ActivityAttributes {
  // Static half: fixed at request time, never updatable.
  let orderID: String
  let restaurantName: String

  // Dynamic half: replaced wholesale on every update, and capped at 4 KB.
  struct ContentState: Codable, Hashable {
    var step: Step
    var eta: Date
    var courierName: String?
  }

  enum Step: String, Codable, Hashable { case preparing, collected, nearby, delivered }
}

func startDelivery(_ order: Order) throws -> Activity<DeliveryAttributes>? {
  guard ActivityAuthorizationInfo().areActivitiesEnabled else { return nil }

  let content = ActivityContent(
    state: .init(step: .preparing, eta: order.eta, courierName: nil),
    staleDate: .now.addingTimeInterval(15 * 60))   // context.isStale after this

  return try Activity.request(
    attributes: DeliveryAttributes(orderID: order.id, restaurantName: order.restaurant),
    content: content,
    pushType: .token)
}

func courierIsNearby(_ activity: Activity<DeliveryAttributes>, name: String) async {
  var state = activity.content.state
  state.step = .nearby
  state.courierName = name          // fine: it lives in ContentState

  // state.restaurantName = "..."   // impossible: attributes are frozen at request time

  await activity.update(
    ActivityContent(state: state, staleDate: .now.addingTimeInterval(600)),
    alertConfiguration: AlertConfiguration(title: "Your courier is nearby",
                                           body: "Two minutes away",
                                           sound: .default))
}

// After a relaunch the handle is gone — recover it, don't start a second activity.
let running = Activity<DeliveryAttributes>.activities.first

import ActivityKit

// 1. Push-to-start: registered once at launch, before any activity exists.
func observePushToStart() {
  Task {
    for await token in Activity<DeliveryAttributes>.pushToStartTokenUpdates {
      await api.register(startToken: hex(token))
    }
  }
}

// 2. Per-activity token: only exists after the activity starts, and it rotates.
func startTracking(order: Order) throws {
  let activity = try Activity.request(
    attributes: DeliveryAttributes(orderID: order.id, restaurant: order.restaurant),
    content: ActivityContent(state: .init(etaMinutes: 25, stage: .cooking),
                             staleDate: .now.addingTimeInterval(15 * 60),
                             relevanceScore: 100),
    pushType: .token)

  Task {
    // WRONG: `let token = await activity.pushTokenUpdates.first(where: { _ in true })`
    // registers one token and goes deaf when the system rotates it.
    for await token in activity.pushTokenUpdates {
      await api.register(updateToken: hex(token), for: order.id)
    }
  }
}

func hex(_ data: Data) -> String { data.map { String(format: "%02x", $0) }.joined() }

