struct DeliveryLiveActivity: Widget {
  var body: some WidgetConfiguration {
    ActivityConfiguration(for: DeliveryAttributes.self) { context in
      // Required: devices without an Island, and the banner on update, use this.
      LockScreenView(context: context)
        .activityBackgroundTint(.black.opacity(0.6))
    } dynamicIsland: { context in
      DynamicIsland {
        DynamicIslandExpandedRegion(.leading) { CourierAvatar(context.state.courier) }
        DynamicIslandExpandedRegion(.trailing) {
          Text(context.state.eta, style: .timer).monospacedDigit()
        }
        DynamicIslandExpandedRegion(.center) { Text(context.attributes.restaurant) }
        DynamicIslandExpandedRegion(.bottom) {
          Link(destination: URL(string: "delivery://order/\(context.attributes.orderID)")!) {
            Text("Track order")
          }
        }
      } compactLeading: {
        Image(systemName: "bicycle")            // used only while yours is the sole activity
      } compactTrailing: {
        Text(context.state.eta, style: .timer)
          .monospacedDigit()
          .frame(width: 44)                     // fixed width, or the Island jitters
      } minimal: {
        // The presentation you get whenever another app also has an activity running:
        // it must identify your app on its own.
        Image(systemName: "bicycle")
      }
      .keylineTint(.orange)
      .widgetURL(URL(string: "delivery://order/\(context.attributes.orderID)"))
    }
  }
}

struct BuildStatusView: View {
  @Environment(\.widgetRenderingMode) private var renderingMode
  let build: Build

  var body: some View {
    VStack(alignment: .leading, spacing: 6) {
      Text("Build \(build.number)")
        .font(.headline)
        .widgetAccentable()          // this group takes the user's tint in .accented mode

      // WRONG: hue is the only signal, so .vibrant and .accented give two identical dots.
      // Circle().fill(build.passing ? .green : .red).frame(width: 10, height: 10)

      // RIGHT: the glyph carries the state, colour is decoration on top of it.
      Label(build.passing ? "Passing" : "Failing",
            systemImage: build.passing ? "checkmark.circle.fill" : "xmark.octagon.fill")
        .foregroundStyle(renderingMode == .fullColor
                         ? (build.passing ? Color.green : Color.red)
                         : Color.primary)

      Image(build.authorAvatar)
        .widgetAccentedRenderingMode(.desaturated)
    }
    // Required since iOS 17 — the system strips this where a background does not belong.
    .containerBackground(for: .widget) {
      LinearGradient(colors: [.indigo, .black], startPoint: .top, endPoint: .bottom)
    }
  }
}

