import UniformTypeIdentifiers

final class ShareViewController: SLComposeServiceViewController {
  private let groupID = "group.com.example.clips"

  override func didSelectPost() {
    guard let provider = (extensionContext?.inputItems.first as? NSExtensionItem)?
            .attachments?.first,
          provider.hasItemConformingToTypeIdentifier(UTType.movie.identifier) else {
      extensionContext?.completeRequest(returningItems: nil); return
    }

    provider.loadFileRepresentation(for: .movie) { [self] url, _, _ in
      guard let url else { extensionContext?.completeRequest(returningItems: nil); return }

      // This URL dies the moment the closure returns — stage it in the App Group first.
      let staged = FileManager.default
        .containerURL(forSecurityApplicationGroupIdentifier: groupID)!
        .appending(path: UUID().uuidString + "." + url.pathExtension)
      try? FileManager.default.copyItem(at: url, to: staged)

      enqueueUpload(of: staged)
      extensionContext?.completeRequest(returningItems: nil)   // the process ends here
    }
  }

  private func enqueueUpload(of file: URL) {
    // WRONG: dies with the process a few milliseconds later.
    // URLSession.shared.uploadTask(with: request, fromFile: file).resume()

    let config = URLSessionConfiguration.background(withIdentifier: "clips.upload")
    config.sharedContainerIdentifier = groupID    // mandatory in an extension
    var request = URLRequest(url: uploadEndpoint)
    request.httpMethod = "PUT"
    URLSession(configuration: config)
      .uploadTask(with: request, fromFile: file)  // file-backed body only
      .resume()
  }
}

import AppIntents

struct LogDrinkIntent: AppIntent {
  static let title: LocalizedStringResource = "Log a drink"
  static let description = IntentDescription("Adds a drink to today's journal.")

  @Parameter(title: "Drink", requestValueDialog: "Which drink?")
  var drink: DrinkEntity                    // an AppEntity, resolved by an EntityStringQuery

  @Parameter(title: "Size", default: .medium)
  var size: DrinkSize

  // The sentence Shortcuts shows and Siri reads back.
  // Anything omitted here is hidden behind "Show More" and looks unset to the user.
  static var parameterSummary: some ParameterSummary {
    Summary("Log a \(\.$size) \(\.$drink)")
  }

  func perform() async throws -> some IntentResult & ProvidesDialog {
    try await Journal.shared.add(drinkID: drink.id, size: size)
    return .result(dialog: "Logged a \(size.name) \(drink.name).")
  }
}

struct BrewlogShortcuts: AppShortcutsProvider {
  static var appShortcuts: [AppShortcut] {
    AppShortcut(
      intent: LogDrinkIntent(),
      phrases: [
        // \(.applicationName) is mandatory — the build fails without it.
        "Log a coffee in \(.applicationName)",
        "Add a drink to \(.applicationName)"
      ],
      shortTitle: "Log a drink",
      systemImageName: "cup.and.saucer.fill")
  }
}

// Whenever the user's list of drinks changes, re-register the dynamic parameter values.
func drinksDidChange() {
  BrewlogShortcuts.updateAppShortcutParameters()
}

import UserNotifications

final class NotificationService: UNNotificationServiceExtension {
  private var contentHandler: ((UNNotificationContent) -> Void)?
  private var bestAttempt: UNMutableNotificationContent?

  override func didReceive(
    _ request: UNNotificationRequest,
    withContentHandler contentHandler: @escaping (UNNotificationContent) -> Void
  ) {
    self.contentHandler = contentHandler
    let content = request.content.mutableCopy() as! UNMutableNotificationContent
    self.bestAttempt = content

    // Cheap and essential first: this must survive a timeout.
    content.body = MessageCrypto.decrypt(content.body)

    guard let raw = request.content.userInfo["image-url"] as? String,
          let url = URL(string: raw) else { contentHandler(content); return }

    let config = URLSessionConfiguration.default
    config.timeoutIntervalForRequest = 12          // finish well inside the ~30 s budget
    URLSession(configuration: config).downloadTask(with: url) { temp, _, _ in
      if let temp {
        // The system moves the attachment file, and temp dies with this closure.
        let owned = temp.deletingLastPathComponent().appending(path: "preview.jpg")
        try? FileManager.default.moveItem(at: temp, to: owned)
        if let attachment = try? UNNotificationAttachment(identifier: "preview", url: owned) {
          content.attachments = [attachment]
        }
      }
      contentHandler(content)
    }.resume()
  }

  override func serviceExtensionTimeWillExpire() {
    // Without this the user gets the original, still-encrypted payload.
    if let contentHandler, let bestAttempt { contentHandler(bestAttempt) }
  }
}

import OSLog
import WidgetKit

private let log = Logger(subsystem: "com.example.notes.widget", category: "timeline")

struct NotesProvider: TimelineProvider {
  func placeholder(in context: Context) -> NotesEntry { .placeholder }

  func getSnapshot(in context: Context, completion: @escaping (NotesEntry) -> Void) {
    completion(.placeholder)
  }

  func getTimeline(in context: Context, completion: @escaping (Timeline<NotesEntry>) -> Void) {
    // print(...) writes to stdout, which nobody is capturing for this process.
    log.debug("timeline for \(String(describing: context.family), privacy: .public)")

    do {
      let notes = try SharedStore.recent(limit: 3)
      // Full-resolution assets are how a widget hits its memory ceiling and shows
      // "Unable to Load". Downsample to the size actually drawn.
      let thumb = ImageDownsampler.thumbnail(at: notes.first?.imageURL, maxPixel: 240)
      completion(Timeline(entries: [NotesEntry(date: .now, notes: notes, thumb: thumb)],
                          policy: .after(.now.addingTimeInterval(900))))
    } catch {
      // Returning here without calling completion looks exactly like a crash.
      log.error("App Group read failed: \(error.localizedDescription, privacy: .public)")
      completion(Timeline(entries: [.placeholder],
                          policy: .after(.now.addingTimeInterval(300))))
    }
  }
}

