import AppIntents
import WidgetKit
import SwiftUI

struct SetLockIntent: SetValueIntent {
  static let title: LocalizedStringResource = "Lock the front door"

  @Parameter(title: "Locked") var value: Bool

  func perform() async throws -> some IntentResult {
    try await LockAPI.setLocked(value)   // must throw: that is what reverts the optimistic flip
    SharedState.isLocked = value         // App Group, so the provider can read it back
    return .result()
  }
}

struct LockValueProvider: ControlValueProvider {
  let previewValue = true                // shown in the gallery — no I/O here

  func currentValue() async throws -> Bool {
    SharedState.isLocked                 // runs in the extension; it cannot ask the app
  }
}

struct FrontDoorControl: ControlWidget {
  var body: some ControlWidgetConfiguration {
    StaticControlConfiguration(kind: "com.example.home.lock",
                               provider: LockValueProvider()) { isLocked in
      ControlWidgetToggle("Front door", isOn: isLocked, action: SetLockIntent()) { on in
        Label(on ? "Locked" : "Unlocked",
              systemImage: on ? "lock.fill" : "lock.open.fill")
      }
      .tint(.green)
    }
    .displayName("Front Door")
    .description("Lock or unlock the front door.")
  }
}

// In the app, after any change the control did not make itself:
func lockStateChangedElsewhere(_ locked: Bool) {
  SharedState.isLocked = locked
  ControlCenter.shared.reloadControls(ofKind: "com.example.home.lock")
}
